  invalid_operation_id_error: struct {};
  operation_identity_reused_error: struct {};
  internal_error: InternalError;

  success: struct {
    service_id: string;
    service_name: string?;
    service_role: ServiceRole;
  };

  invalid_registration_token_error: struct {};
  organization_not_found_error: struct {};
} = 304691;

